insert into sources (code, name, note, url) values ('kich_ban_15_trang', 'Kịch bản 15 trang Món Ngon Mỗi Ngày (nguồn nội bộ)', 'Danh mục 90 món (trang 8), 7 công thức mẫu (trang 9–12), thực đơn 7 ngày (trang 13), bản đồ tính năng (trang 6), lộ trình (trang 14–15).', NULL) on conflict do nothing;
insert into sources (code, name, note, url) values ('calocalo_vn_fct', 'Bảng Thành phần Thực phẩm Việt Nam, Viện Dinh dưỡng Quốc gia (Bộ Y tế) — qua CaloCalo', 'Số liệu theo 100 g món ăn hoàn chỉnh.', 'https://calocalo.app/blog/vietnamese-food-calories/') on conflict do nothing;
insert into sources (code, name, note, url) values ('fao_vn_fct_2017', 'Vietnamese Food Composition Table (Viet Nam, 2017), Ministry of Health — FAO', 'Bản gốc bảng thành phần thực phẩm Việt Nam 2017, 302 trang.', 'https://www.fao.org/food-composition/tables-and-databases/detail/%28viet-nam--2017%29-vietnamese-food-composition-table/en') on conflict do nothing;
insert into sources (code, name, note, url) values ('fitarchive_usda', 'FitArchive — ước tính từ USDA FoodData Central', 'Recipe estimates từ nguyên liệu USDA FoodData Central; không phải đo phòng lab, sai số ±15–20%. CHỈ THAM KHẢO (QĐ1=B): không dùng để tính tag chế độ ăn, không dùng để hiển thị.', 'https://www.fitarchive.app/food-sources/') on conflict do nothing;
insert into sources (code, name, note, url) values ('vien_dinh_duong_rda_2026', 'Viện Dinh dưỡng 2026 — Nhu cầu dinh dưỡng khuyến nghị cho người Việt Nam', 'Protein ~0,93 g/kg/ngày; không duy trì >2 g/kg/ngày dài hạn; chất béo 20–25% năng lượng; protein tham chiếu ghi nhãn 50 g/ngày. Chỉ dùng cho quy tắc chế độ ăn, không phải chỉ định y tế.', NULL) on conflict do nothing;
insert into sources (code, name, note, url) values ('who_healthy_diet', 'WHO — Healthy diet (fact sheet)', 'Carb 45–75%, chất béo <30% (Việt Nam 20–25%), đường tự do <10%, muối <5 g/ngày, rau/củ/quả ≥400 g/ngày.', 'https://www.who.int/news-room/fact-sheets/detail/healthy-diet?swcfpc=1') on conflict do nothing;
insert into sources (code, name, note, url) values ('bo_y_te_10_khuyen_nghi', 'Bộ Y tế — 10 Khuyến nghị dinh dưỡng hợp lý đến năm 2030', 'Hạn chế đồ chiên rán/đồ ăn nhanh, thực phẩm nhiều mỡ/mặn/ngọt. Chỉ dùng cho quy tắc chế độ ăn.', NULL) on conflict do nothing;
