insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, time_text, ingredients_text, steps_text, tip) values ('1dc5b0ee-a39f-5a60-9146-eab2622ee769', '3a854ee6-9fae-5871-8ee0-9e666de75b0d', 'Phở bò', 'Bac', true, '4 người', 'khoảng 3 giờ (hầm) hoặc 60 phút bản rút gọn', 'xương ống bò 1 kg; thịt bò bắp/nạm 600 g; thịt bò tái (thăn) 300 g; bánh phở 1 kg; hành tây 2 củ, gừng 100 g, hành khô 4 củ; quế, hồi, thảo quả, đinh hương (1 gói gia vị phở); hành lá, mùi, húng quế, giá, chanh, ớt; nước mắm, muối, đường phèn.', '1) Chần xương 5 phút, rửa sạch. 2) Nướng hành, gừng thơm. 3) Hầm xương 2–3 giờ lửa nhỏ, vớt bọt, cho gia vị đã rang thơm vào 30 phút cuối. 4) Luộc nạm/bắp chín, thái mỏng. 5) Nêm nước dùng: nước mắm + đường phèn, vị mặn thanh, không gắt. 6) Trụng bánh phở, xếp thịt, chan nước sôi già, rắc hành mùi.', 'Nước dùng phải sôi thật già mới “chín” được thịt tái; không đun gia vị quá lâu sẽ đắng.') on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, time_text, ingredients_text, steps_text, tip) values ('f2dc8fd6-0b84-549d-97b2-b7855e7df5c7', 'faa77d86-0b21-50ca-8414-f204602a8b32', 'Bún chả', 'Bac', true, '4 người', 'khoảng 60 phút', 'thịt ba chỉ 400 g; thịt nạc vai xay 400 g; bún tươi 1 kg; đu đủ xanh/cà rốt làm dưa góp; tỏi, ớt, sả (tuỳ chọn), hành tím; nước mắm, đường, giấm, nước dừa hoặc nước lọc; rau sống: xà lách, tía tô, kinh giới, húng.', '1) Ướp thịt miếng và thịt viên với hành tím băm, nước mắm, đường, tiêu, chút dầu ăn 30 phút. 2) Nướng than (hoặc nồi chiên không dầu 200°C, 12–15 phút) đến xém cạnh. 3) Pha nước chấm: nước ấm + đường + nước mắm + giấm, vị chua ngọt mặn cân bằng, thả dưa góp và tỏi ớt. 4) Cho chả nóng vào bát nước chấm, ăn kèm bún và rau sống.', 'Cho chả vào nước chấm khi còn nóng để chả thấm và nước chấm thơm mùi nướng.') on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, time_text, ingredients_text, steps_text, tip) values ('c53d84df-7758-5a84-92c5-e81a496a96c6', 'e3d7de0c-d541-5277-aa22-2d5a52442ec4', 'Bún bò Huế', 'Trung', true, '4 người', 'khoảng 90 phút', 'bún sợi lớn 1 kg; bắp bò 600 g; giò heo 500 g (tuỳ chọn); chả Huế/chả bò 200 g; sả 6 cây; mắm ruốc Huế 2 muỗng canh; ớt, sa tế; hành tây, hành lá, rau răm; rau ăn kèm: bắp chuối bào, giá, rau thơm.', '1) Luộc bắp bò và giò với sả đập dập, vớt bọt. 2) Hoà mắm ruốc với nước lạnh, để lắng, chỉ lấy nước trong cho vào nồi. 3) Phi sả băm và ớt với dầu màu điều, cho vào nồi tạo màu và vị cay thơm. 4) Nêm muối, đường, nước mắm; thịt chín vớt ra thái. 5) Trụng bún, xếp thịt, chả, chan nước dùng, rắc hành răm.', 'Cay và thơm sả phải rõ nhưng không át vị bò; ăn kèm chanh và ớt tươi.') on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, time_text, ingredients_text, steps_text, tip) values ('b973c92b-9f88-503e-9e93-50bcce06ff3e', 'b6fcb00f-4477-5f6e-9905-a5626a60d501', 'Mì Quảng gà/tôm thịt', 'Trung', true, '4 người', 'khoảng 60 phút', 'mì Quảng (sợi mì gạo nghệ) 800 g; tôm 300 g; thịt ba chỉ 300 g; trứng cút 12 quả; đậu phộng rang; bánh tráng nướng; rau sống: cải con, bắp chuối, húng quế; nghệ, hành, tỏi; nước dùng gà/heo 800 ml (chỉ chan xâm xấp).', '1) Ướp tôm thịt với nghệ băm, nước mắm, tiêu. 2) Xào tôm thịt săn, cho nước dùng vào nấu thành “nước nhưn” đậm vị. 3) Trụng mì, xếp tôm thịt, trứng cút, chan ít nước nhưn. 4) Rắc đậu phộng, hành lá, bẻ bánh tráng nướng lên trên, trộn đều khi ăn.', 'Thiếu bánh tráng nướng và đậu phộng là mất một nửa chất mì Quảng; rau cải con cay nồng là điểm nhận diện.') on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, time_text, ingredients_text, steps_text, tip) values ('b092cf44-85b3-58b5-9944-3c3dfdd635e2', '2d478aac-e3e0-5202-a892-cee66eaaa8ca', 'Hủ tiếu Nam Vang', 'Nam', true, '4 người', 'khoảng 90 phút', 'hủ tiếu dai 600 g; xương ống heo 800 g; thịt nạc heo 300 g; tôm 200 g; gan heo 150 g (tuỳ chọn); mực khô nhỏ hoặc củ cải trắng tạo ngọt; cần tây, hẹ, xà lách, giá; tỏi phi, hành phi; thịt băm xào tỏi.', '1) Hầm xương với củ cải, vớt bọt kỹ cho nước trong. 2) Luộc thịt, tôm, gan trong nước dùng, thái lát. 3) Xào thịt băm với tỏi cho thơm. 4) Trụng hủ tiếu vừa mềm (trụng lâu sẽ bở), xếp topping, cho thịt băm, chan nước dùng, rắc hẹ, cần, tỏi phi. 5) Hai cách ăn: chan nước hoặc ăn khô trộn sốt tương đen.', 'Nước dùng hủ tiếu cần vị ngọt thanh từ xương và củ cải, không nêm đường gắt.') on conflict do nothing;
insert into recipes (id, dish_id, dish_name, region, in_90, servings_text, time_text, ingredients_text, steps_text, tip) values ('6c890c6a-2613-54dc-8f66-d3b5509f3f8f', '21d9b04e-493a-54a1-bd40-c42814b69c7a', 'Cơm tấm sườn bì chả', 'Nam', true, '4 người', 'khoảng 75 phút', 'gạo tấm 600 g; sườn cốt lết 600 g; bì heo + thính; chả trứng (trứng, thịt băm, miến, nấm mèo); sả, tỏi, mật ong, sữa tươi (ướp sườn mềm); mỡ hành; đồ chua cà rốt — củ cải; nước mắm pha chua ngọt.', '1) Ướp sườn với sả tỏi băm, nước mắm, mật ong, sữa, tiêu ít nhất 1 giờ (tốt nhất qua đêm). 2) Nướng sườn lửa vừa đến xém thơm, phết mỡ hành. 3) Nấu cơm tấm hơi khô hơn cơm thường. 4) Hấp chả trứng chín, cắt miếng. 5) Bày cơm, sườn, bì, chả, đồ chua, chan mỡ hành và nước mắm pha.', 'Nước mắm cơm tấm phải sánh nhẹ và ngọt rõ hơn nước chấm bún chả; sườn ngon nhất khi nướng than.') on conflict do nothing;
